class PanelFile
{
public:
	void Draw(int layer);
};

class TextString
{
public:
	void Draw();
	void changeText(const char *text);
	void makeBox(int width, int height);
	void changePos(int x, int y);
};

class PanelQuad
{
public:
	void TurnOn(bool on);
};

struct BFE_Beach
{
	int location;
	bool locked;
	char pad0[3];
	int unused;
	int main_beach;
	int secondary_beaches[2];
	bool new_challenges;
	bool done;
	char pad1[2];
};

class MapData
{
public:
	void DrawPath(float loading_progress);
};

extern const char *ksGlobalTextArray[];
enum { GT_FE_MENU_RETURN_FE_QUESTION };

class BeachFrontEnd
{
	static const int max_blink_index = 3;
	char pad0000[76];
	int highlighted;
	char pad0050[176];
	PanelFile panel;
	char pad0101[491];
	BFE_Beach beaches[47];
	int current_beach_index;
	char pad0814[12];
	int home_beach;
	char pad0824[112];
	int fe_return;
	char pad0898[108];
	TextString *return_question;
	char pad0908[16];
	int blink_index;
	char pad091c[188];
	PanelQuad *here[47];
	char pad0a94[212];
	PanelQuad *select_circle[47][3];
	char pad0d9c[328];
	MapData map;
	bool no_progress_path;
	char pad0f05[3];
	int map_wait_loading;

public:
	void DrawMap(float loading_progress);
};

void BeachFrontEnd::DrawMap(float loading_progress)
{
	if(highlighted == fe_return)
	{
		panel.Draw(0);

		return_question->Draw();

		if(map_wait_loading > 0)
			map_wait_loading--;
		else if(map_wait_loading == 0)
		{
			map_wait_loading = -1;
			return_question->changeText(ksGlobalTextArray[GT_FE_MENU_RETURN_FE_QUESTION]);
			return_question->makeBox(200, 100);
			return_question->changePos(320, 200);
		}

		panel.Draw(1);
	}
	else
	{
		blink_index++;
		if(blink_index >= max_blink_index) blink_index = 0;

		int current_main_beach = current_beach_index;
		if(beaches[current_beach_index].main_beach != -1)
			current_main_beach = beaches[current_beach_index].main_beach;

		for(int j=0; j<max_blink_index; j++)
			if(select_circle[current_main_beach][j])
				select_circle[current_main_beach][j]->TurnOn(j == blink_index);

		if(home_beach != -1 && here[home_beach]) here[home_beach]->TurnOn(true);

		panel.Draw(0);

		// draw map path
		if(!no_progress_path)
			map.DrawPath(loading_progress);

		panel.Draw(1);
	}
}
